        ///<summary>
        ///
        ///</summary>
        /// <param name="funding"> </param>
        /// <param name="beneficiary"> </param>
        /// <param name="delegate"> </param>
        /// <param name="total_amount"> </param>
        /// <param name="duration_seconds"> </param>
        /// <param name="release_interval_seconds"> </param>
        public async Task CreateStream(PaymentTransaction funding, Algorand.Address beneficiary, Algorand.Address @delegate, ulong total_amount, ulong duration_seconds, ulong release_interval_seconds, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
        {
            _tx_boxes ??= new List<BoxRef>();
            _tx_transactions ??= new List<Transaction>();
            _tx_assets ??= new List<ulong>();
            _tx_apps ??= new List<ulong>();
            _tx_accounts ??= new List<Address>();
            _tx_transactions.AddRange(new List<Transaction> { funding });
            byte[] abiHandle = { 192, 43, 159, 64 };
            var beneficiaryAbi = new AVM.ClientGenerator.ABI.ARC4.Types.Address(); beneficiaryAbi.From(beneficiary);
            var delegateAbi = new AVM.ClientGenerator.ABI.ARC4.Types.Address(); delegateAbi.From(@delegate);
            var total_amountAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); total_amountAbi.From(total_amount);
            var duration_secondsAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); duration_secondsAbi.From(duration_seconds);
            var release_interval_secondsAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); release_interval_secondsAbi.From(release_interval_seconds);

            var result = await base.CallApp(new List<object> { abiHandle, funding, beneficiaryAbi, delegateAbi, total_amountAbi, duration_secondsAbi, release_interval_secondsAbi }, _tx_fee: _tx_fee, _tx_callType: _tx_callType, _tx_roundValidity: _tx_roundValidity, _tx_note: _tx_note, _tx_sender: _tx_sender, _tx_transactions: _tx_transactions, _tx_apps: _tx_apps, _tx_assets: _tx_assets, _tx_accounts: _tx_accounts, _tx_boxes: _tx_boxes);

        }

